async function getQueuedReservePublication(
  group
) {
  const result =
    await getReserveList({
      group,
      status:
        "queued",
      limit:
        20
    });

  const entries =
    result?.reserve?.entries ||
    [];

  for (
    const reserve of
    entries
  ) {
    const itemId =
      String(
        reserve?.currentItemId ||
        reserve?.itemId ||
        ""
      )
        .trim()
        .toUpperCase();

    if (/^MLB\d+$/.test(itemId)) {
      return {
        reserve,
        itemId
      };
    }
  }

  return null;
}

async function prepareSpecificReadyBatchItem(
  sock,
  group,
  itemId
) {
  let entry =
    await getReadyItem(
      group,
      {
        ignorePreviewMemory:
          true,
        itemId
      }
    );

  if (entry) {
    return entry;
  }

  for (
    let attempt = 1;
    attempt <= 8;
    attempt += 1
  ) {
    if (!isSocketActive(sock)) {
      throw connectionClosedError();
    }

    if (!isAutomaticSendWindowOpen()) {
      throw automaticWindowClosedError();
    }

    const awaiting =
      await getAwaitingAffiliateItem(
        group,
        {
          itemId
        }
      );

    if (!awaiting) {
      break;
    }

    const generated =
      await fillNextAffiliateLink(
        sock,
        {
          group,
          batchMode:
            true,
          itemId
        }
      );

    if (generated) {
      entry =
        await waitForReadyBatchItem(
          group,
          {
            itemId
          }
        );

      if (entry) {
        return entry;
      }
    }

    await sleep(250);
  }

  return getReadyItem(
    group,
    {
      ignorePreviewMemory:
        true,
      itemId
    }
  );
}

async function processSemiAutomaticPerfumesGroup(
  sock
) {
  const group =
    "perfumes";

  const meta =
    AUTO_BATCH_LABELS[group];

  console.log(
    `${meta.emoji} Lote iniciado: ${meta.label} | SEMI-AUTOMÁTICO | fila curada RESERVA PERFUMES`
  );

  let sentCount =
    0;

  while (
    sentCount < AUTO_BATCH_SIZE
  ) {
    if (!isSocketActive(sock)) {
      throw connectionClosedError();
    }

    if (!isAutomaticSendWindowOpen()) {
      throw automaticWindowClosedError();
    }

    if (manualModeEnabled) {
      console.log(
        `${meta.emoji} Lote ${meta.label} interrompido: modo manual ativo.`
      );
      break;
    }

    const queuedReserve =
      await getQueuedReservePublication(
        group
      );

    let itemId =
      queuedReserve?.itemId ||
      null;

    if (!itemId) {
      let materialized =
        null;

      try {
        materialized =
          await materializeReserveItem(
            group
          );
      } catch (error) {
        console.error(
          `${meta.emoji} ⚠️ Fila curada ${meta.label}:`,
          error?.message ||
          error
        );
        break;
      }

      if (
        !materialized?.queued
      ) {
        if (materialized?.empty) {
          console.log(
            `${meta.emoji} Fila curada vazia. Nenhum perfume será publicado neste lote.`
          );
        } else {
          console.log(
            `${meta.emoji} Nenhum perfume utilizável foi encontrado na fila curada nesta tentativa.`
          );
        }
        break;
      }

      itemId =
        String(materialized.itemId || "")
          .trim()
          .toUpperCase();

      console.log(
        `${meta.emoji} 🛟 Perfume curado #${materialized.reserve?.id || "?"}: ${materialized.title || itemId}`
      );
    } else {
      console.log(
        `${meta.emoji} 🔄 Retomando perfume já materializado da fila curada: ${itemId}`
      );
    }

    if (!/^MLB\d+$/.test(itemId)) {
      console.log(
        `${meta.emoji} ⚠️ Item da fila curada sem itemId válido. Vou tentar no próximo ciclo.`
      );
      break;
    }

    const entry =
      await prepareSpecificReadyBatchItem(
        sock,
        group,
        itemId
      );

    if (!entry) {
      console.log(
        `${meta.emoji} ⚠️ Não consegui preparar ${itemId} agora. Ele continua guardado para uma próxima tentativa.`
      );
      break;
    }

    const sent =
      await sendEntryAutomatically(
        sock,
        entry,
        group
      );

    if (!sent) {
      try {
        await setStatus(
          itemId,
          "retry"
        );
      } catch {
        // O erro original já foi registrado por sendEntryAutomatically.
      }

      rememberHandled(
        recentSentProducts,
        entry,
        60000
      );

      console.log(
        `${meta.emoji} ⚠️ Falha no envio; perfume mantido para nova tentativa em outro ciclo.`
      );
      break;
    }

    sentCount +=
      1;

    await sleep(2500);
  }

  console.log(
    `${meta.emoji} Lote concluído: ${meta.label} → ${sentCount}/${AUTO_BATCH_SIZE} | origem: fila curada`
  );

  return sentCount;
}

